          name={`product-${product.slug}`}
          share="morph"
          default="none"
        >
          <div
            className="product-hero"
            style={{ backgroundColor: product.color }}
          />
        </ViewTransition>
        <Suspense
          fallback={
            <ViewTransition exit="slide-down" default="none">
              <DetailsSkeleton />
            </ViewTransition>
          }
        >
